/**
 * Frontend mirror of the serialized Rust `PlantGenome` V1 contract.
 *
 * Field names intentionally remain snake_case because Rust's serde output is
 * the wire representation. This is presentation data only: it must be
 * generated by the native domain and is never created or modified here.
 */
export type Morphology = "FERN" | "SUCCULENT" | "WILDFLOWER" | "VINE" | "SHRUB";
export type LeafSide = "LEFT" | "RIGHT";
export type LeafShape = "OVAL" | "LANCEOLATE" | "SERRATED" | "ROUND";
export type FlowerKind = "BLOOM" | "BELL" | "STAR" | "CLUSTER";

export type Rgb = {
  red: number;
  green: number;
  blue: number;
};

export type Stem = {
  height: number;
  thickness: number;
  curvature: number;
  branch_count: number;
};

export type Leaf = {
  side: LeafSide;
  position: number;
  angle_degrees: number;
  size: number;
  shape: LeafShape;
};

export type Flower = {
  kind: FlowerKind;
  petal_count: number;
  size: number;
  tilt_degrees: number;
};

export type Palette = {
  stem: Rgb;
  leaf_primary: Rgb;
  leaf_secondary: Rgb;
  flower_primary: Rgb;
  flower_secondary: Rgb;
};

export type Effects = {
  glow: number;
  dew_drops: number;
  pollen: number;
  breeze_offset: number;
};

export type PlantGenome = {
  generator_version: number;
  morphology: Morphology;
  stem: Stem;
  leaves: readonly Leaf[];
  flower: Flower;
  palette: Palette;
  effects: Effects;
};
